func (this *Bitrue) Nonce() int64 {
	return this.Milliseconds() - *this.SafeInteger(this.Options, "timeDifference", 0)
}

/**
 * @method
 * @name bitrue#fetchStatus
 * @description the latest known information on the availability of the exchange API
 * @see https://github.com/Bitrue-exchange/Spot-official-api-docs#test-connectivity
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [status structure]{@link https://docs.ccxt.com/?id=exchange-status-structure}
 */
func (this *Bitrue) FetchStatusAsync(optionalArgs ...any) <-chan AsyncResult[Status] {
	ch := make(chan AsyncResult[Status], 1)
	go this.fetchStatusBody(ch, optionalArgs...)
	return ch
}
func (this *Bitrue) fetchStatusBody(ch chan AsyncResult[Status], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.SpotV1PublicGetPing(params)
	if r.Err != nil {
		panic(r.Err)
	}
	response := r.Raw
	//
	// empty means working status.
	//
	//     {}
	//
	var keys []string = ObjectKeys(response)
	var keysLength int = len(keys)
	var formattedStatus string = "ok"
	if keysLength > 0 {
		formattedStatus = "maintenance"
	}

	ch <- AsyncResult[Status]{Value: StatusFromMap(map[string]any{
		"status":  formattedStatus,
		"updated": nil,
		"eta":     nil,
		"url":     nil,
		"info":    response,
	})}
	return nil
}

/**
 * @method
 * @name bitrue#fetchTime
 * @description fetches the current integer timestamp in milliseconds from the exchange server
 * @see https://github.com/Bitrue-exchange/Spot-official-api-docs#check-server-time
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {int} the current integer timestamp in milliseconds from the exchange server
 */
func (this *Bitrue) FetchTimeAsync(optionalArgs ...any) <-chan AsyncResult[*int64] {
	ch := make(chan AsyncResult[*int64], 1)
	go this.fetchTimeBody(ch, optionalArgs...)
	return ch
}
func (this *Bitrue) fetchTimeBody(ch chan AsyncResult[*int64], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.SpotV1PublicGetTime(params)
	if r.Err != nil {
		panic(r.Err)
	}
	var response map[string]any = r.Value

	//
	//     {
	//         "serverTime":1635467280514
	//     }
	//
	ch <- AsyncResult[*int64]{Value: this.SafeInteger(response, "serverTime")}
	return nil
}

