func (this *Bitrue) SetLeverageAsync(leverage int64, optionalArgs ...any) <-chan AsyncResult[map[string]any] {
	ch := make(chan AsyncResult[map[string]any], 1)
	go this.setLeverageBody(ch, leverage, optionalArgs...)
	return ch
}
func (this *Bitrue) setLeverageBody(ch chan AsyncResult[map[string]any], leverage int64, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	if symbol == nil {
		panic(ArgumentsRequired(this.Id + " setLeverage() requires a symbol argument"))
	}
	if (leverage < 1) || (leverage > 125) {
		panic(BadRequest(this.Id + " leverage should be between 1 and 125"))
	}
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var response map[string]any = map[string]any{}
	var request map[string]any = map[string]any{
		"contractName": market["id"],
		"leverage":     leverage,
	}
	if market["swap"] != true {
		panic(NotSupported(this.Id + " setLeverage only support swap markets"))
	}
	if market["linear"] == true {

		r1 := <-this.FapiV2PrivatePostLevelEdit(this.Extend(request, params))
		if r1.Err != nil {
			panic(r1.Err)
		}
		response = r1.Value
	} else if market["inverse"] == true {

		r2 := <-this.DapiV2PrivatePostLevelEdit(this.Extend(request, params))
		if r2.Err != nil {
			panic(r2.Err)
		}
		response = r2.Value
	}

	ch <- AsyncResult[map[string]any]{Value: response}
	return nil
}
func (this *Bitrue) ParseMarginModification(data any, optionalArgs ...any) map[string]any {
	//
	// setMargin
	//
	//     {
	//         "code": 0,
	//         "msg": "success"
	//         "data": null
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	return map[string]any{
		"info":       data,
		"symbol":     this.SafeString(market, "symbol"),
		"type":       nil,
		"marginMode": "isolated",
		"amount":     nil,
		"total":      nil,
		"code":       nil,
		"status":     nil,
		"timestamp":  nil,
		"datetime":   nil,
	}
}

/**
 * @method
 * @name bitrue#setMargin
 * @description Either adds or reduces margin in an isolated position in order to set the margin to a specific value
 * @see https://www.bitrue.com/api-docs#modify-isolated-position-margin-trade-hmac-sha256
 * @see https://www.bitrue.com/api_docs_includes_file/delivery.html#modify-isolated-position-margin-trade-hmac-sha256
 * @param {string} symbol unified market symbol of the market to set margin in
 * @param {float} amount the amount to set the margin to
 * @param {object} [params] parameters specific to the exchange API endpoint
 * @returns {object} A [margin structure]{@link https://github.com/ccxt/ccxt/wiki/Manual#add-margin-structure}
 */
func (this *Bitrue) SetMarginAsync(symbol any, amount any, optionalArgs ...any) <-chan AsyncResult[MarginModification] {
	ch := make(chan AsyncResult[MarginModification], 1)
	go this.setMarginBody(ch, symbol, amount, optionalArgs...)
	return ch
}
func (this *Bitrue) setMarginBody(ch chan AsyncResult[MarginModification], symbol any, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	if market["swap"] != true {
		panic(NotSupported(this.Id + " setMargin only support swap markets"))
	}
	var response any = nil
	var request map[string]any = map[string]any{
		"contractName": market["id"],
		"amount":       this.ParseToNumeric(amount),
	}
	if market["linear"] == true {

		r1 := <-this.FapiV2PrivatePostPositionMargin(this.Extend(request, params))
		if r1.Err != nil {
			panic(r1.Err)
		}
		response = r1.Raw
	} else if market["inverse"] == true {

		r2 := <-this.DapiV2PrivatePostPositionMargin(this.Extend(request, params))
		if r2.Err != nil {
			panic(r2.Err)
		}
		response = r2.Raw
	}

	//
	//     {
	//         "code": 0,
	//         "msg": "success"
	//         "data": null
	//     }
	//
	ch <- AsyncResult[MarginModification]{Value: MarginModificationFromMap(this.ParseMarginModification(response, market))}
	return nil
}
func (this *Bitrue) Sign(path string, optionalArgs ...any) map[string]any {
	var api []string = GetArgStringSlice(optionalArgs, 0, []string{"public"})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	var requestBody any = nil
	var requestHeaders any = nil
	var typeVar string = api[0]
	var version string = api[1]
	var access string = api[2]
	var apiUrl *string = this.SafeString(this.Urls["api"], typeVar)
	if apiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var endpointPath string = this.ImplodeParams(path, params)
	var url string = *apiUrl + "/" + endpointPath
	if !(((typeVar == "api") && (version == "kline")) || ((typeVar == "open") && (strings.Index(path, "listenKey") >= 0))) {
		url = *apiUrl + "/" + version + "/" + endpointPath
	}
	var paramsOmitted any = this.Omit(params, this.ExtractParams(path))
	if access == "private" {
		this.CheckRequiredCredentials()
		var recvWindow *int64 = this.SafeInteger(this.Options, "recvWindow", 5000)
		if (typeVar == "spot") || (typeVar == "open") {
			var query string = this.Urlencode(this.Extend(map[string]any{
				"timestamp":  this.Nonce(),
				"recvWindow": recvWindow,
			}, paramsOmitted))
			var signature string = this.Hmac(this.Encode(query), this.Encode(this.Secret), sha256)
			query += "&" + "signature=" + signature
			if (method == "GET") || (method == "DELETE") {
				url += "?" + query
				requestHeaders = map[string]any{
					"X-MBX-APIKEY": this.ApiKey,
				}
			} else {
				requestBody = query
				requestHeaders = map[string]any{
					"X-MBX-APIKEY": this.ApiKey,
					"Content-Type": "application/x-www-form-urlencoded",
				}
			}
		} else {
			var timestamp string = strconv.FormatInt(this.Nonce(), 10)
			var signPrefix string = ""
			if typeVar == "fapi" {
				signPrefix = "/fapi"
			} else if typeVar == "dapi" {
				signPrefix = "/dapi"
			}
			var signMessage any = timestamp + method + (signPrefix + "/" + version + "/" + path)
			if method == "GET" {
				if paramsOmittedMap, _ := paramsOmitted.(map[string]any); len(paramsOmittedMap) > 0 {
					signMessage = Add(signMessage, "?"+this.Urlencode(paramsOmitted))
				}
				var signature string = this.Hmac(this.Encode(signMessage), this.Encode(this.Secret), sha256)
				requestHeaders = map[string]any{
					"X-CH-APIKEY": this.ApiKey,
					"X-CH-SIGN":   signature,
					"X-CH-TS":     timestamp,
				}
				url += "?" + this.Urlencode(paramsOmitted)
			} else {
				var query any = this.Extend(map[string]any{
					"recvWindow": recvWindow,
				}, paramsOmitted)
				requestBody = this.Json(query)
				signMessage = Add(signMessage, requestBody)
				var signature string = this.Hmac(this.Encode(signMessage), this.Encode(this.Secret), sha256)
				requestHeaders = map[string]any{
					"Content-Type": "application/json",
					"X-CH-APIKEY":  this.ApiKey,
					"X-CH-SIGN":    signature,
					"X-CH-TS":      timestamp,
				}
			}
		}
	} else {
		if paramsOmittedMap, _ := paramsOmitted.(map[string]any); len(paramsOmittedMap) > 0 {
			url += "?" + this.Urlencode(paramsOmitted)
		}
	}
	var bodyResult any = requestBody
	var headersResult any = requestHeaders
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    bodyResult,
		"headers": headersResult,
	}
}
func (this *Bitrue) HandleErrors(code int64, reason string, url string, method string, headers any, body string, response any, requestHeaders any, requestBody any) any {
	if (code == 418) || (code == 429) {
		panic(DDoSProtection(this.Id + " " + strconv.FormatInt(code, 10) + " " + reason + (" " + body)))
	}
	// error response in a form: { "code": -1013, "msg": "Invalid quantity." }
	// following block contains legacy checks against message patterns in "msg" property
	// will switch "code" checks eventually, when we know all of them
	var statusCode int64 = this.ParseToInt(code)
	if statusCode >= 400 {
		if strings.Index(body, "Price * QTY is zero or less") >= 0 {
			panic(InvalidOrder(this.Id + " order cost = amount * price is zero or less " + body))
		}
		if strings.Index(body, "LOT_SIZE") >= 0 {
			panic(InvalidOrder(this.Id + " order amount should be evenly divisible by lot size " + body))
		}
		if strings.Index(body, "PRICE_FILTER") >= 0 {
			panic(InvalidOrder(this.Id + " order price is invalid, i.e. exceeds allowed price precision, exceeds min price or max price limits or is invalid float value in general, use this.priceToPrecision (symbol, amount) " + body))
		}
	}
	if response == nil {
		return nil // fallback to default error handler
	}
	// check success value for wapi endpoints
	// response in format {'msg': 'The coin does not exist.', 'success': true/false}
	var success *bool = this.SafeBool(response, "success", true)
	var parsedMessage any = nil
	if !(success != nil && *success) {
		var messageInner *string = this.SafeString(response, "msg")
		if messageInner != nil {
			parsedMessage = this.ParseJson(messageInner)
		}
	}
	var errorResponse any = func() any {
		if parsedMessage != nil {
			return parsedMessage
		}
		return response
	}()
	var message *string = this.SafeString(errorResponse, "msg")
	if message != nil {
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], message, this.Id+" "+*message)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], message, this.Id+" "+*message)
	}
	// checks against error codes
	var error *string = this.SafeString(errorResponse, "code")
	if error != nil {
		// https://github.com/ccxt/ccxt/issues/6501
		// https://github.com/ccxt/ccxt/issues/7742
		if (error != nil && *error == "200") || Precise.StringEquals(error, "0") {
			return nil
		}
		// a workaround for {"code":-2015,"msg":"Invalid API-key, IP, or permissions for action."}
		// despite that their message is very confusing, it is raised by Binance
		// on a temporary ban, the API key is valid, but disabled for a while
		if (error != nil && *error == "-2015") && (*this.SafeBool(this.Options, "hasAlreadyAuthenticatedSuccessfully", false)) {
			panic(DDoSProtection(this.Id + " temporary banned: " + body))
		}
		var feedback string = this.Id + " " + body
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], error, feedback)
		panic(ExchangeError(feedback))
	}
	if !(success != nil && *success) {
		panic(ExchangeError(this.Id + " " + body))
	}
	return nil
}
func (this *Bitrue) CalculateRateLimiterCost(api any, method string, path string, params any, optionalArgs ...any) any {
	var config map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = config
	if _, ok := config["noSymbol"]; ok && !(InOp(params, "symbol")) {
		return config["noSymbol"]
	} else if _, ok := config["byLimit"]; ok && (InOp(params, "limit")) {
		var limit *int64 = this.SafeInteger(params, "limit")
		var byLimit []any = SafeListTyped(config, "byLimit")
		for i := 0; i < len(byLimit); i++ {
			var entry any = byLimit[i]
			var threshold *int64 = this.SafeInteger(entry, 0)
			if (limit != nil) && (threshold != nil) && (*limit <= *threshold) {
				return this.SafeNumber(entry, 1)
			}
		}
	}
	return this.SafeValue(config, "cost", 1)
}

func NewBitrue(userConfig map[string]any) *Bitrue {
	p := newBitrue()
	p.Init(userConfig)
	return p
}

func (this *Bitrue) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe(), this)
}

